import argparse
import sys
import json
import os
from collections import defaultdict

def parse_value(value_str):
    if value_str.startswith('-'):
        try:
            return int(value_str[1:])
        except ValueError:
            return value_str
    else:
        try:
            return int(value_str)
        except ValueError:
            return value_str

def add_record(data_file, key_value_pairs):
    records = []
    if os.path.exists(data_file):
        with open(data_file, 'r') as f:
            records = json.load(f)

    for kv in key_value_pairs:
        key, value = kv.split('=', 1)
        value = parse_value(value)
        records.append({key: value})

    with open(data_file, 'w') as f:
        json.dump(records, f)

def render_report(data_file, output_html):
    with open(data_file, 'r') as f:
        records = json.load(f)

    if not records:
        print(0)
        with open(output_html, 'w') as f:
            f.write('<html><head><meta charset="utf-8"><title>Report</title></head><body><table></table></body></html>')
        return

    all_keys = set()
    for record in records:
        all_keys.update(record.keys())

    column_order = []
    for key in all_keys:
        if any(key in record for record in records):
            column_order.append(key)

    html = f'<html><head><meta charset="utf-8"><title>Report</title></head><body><table><thead><tr>{", ".join(column_order)}</tr></thead><tbody>'
    for record in records:
        row = []
        for key in column_order:
            if key in record:
                row.append(str(record[key]))
            else:
                row.append('')
        html += f'<tr>{", ".join(row)}</tr>'

        if 'formula' in record:
            try:
                result = eval(record['formula'], {}, record)
                row[-1] = str(result)
            except:
                row[-1] = ''

        html += f'<tr><td>{", ".join(row)}</td></tr>'

    html += '</tbody></table></body></html>'
    with open(output_html, 'w') as f:
        f.write(html)

    print(len(records))

def main():
    parser = argparse.ArgumentParser(description='Manage and render records.')
    subparsers = parser.add_subparsers(dest='command', required=True)

    add_parser = subparsers.add_parser('add', help='Add records to DATA_FILE')
    add_parser.add_argument('data_file', type=str)
    add_parser.add_argument('key_value_pairs', nargs='+', help='Key=Value pairs')

    render_parser = subparsers.add_parser('render', help='Render records to HTML')
    render_parser.add_argument('data_file', type=str)
    render_parser.add_argument('output_html', type=str)

    args = parser.parse_args()

    if args.command == 'add':
        add_record(args.data_file, args.key_value_pairs)
    elif args.command == 'render':
        render_report(args.data_file, args.output_html)

if __name__ == '__main__':
    main()

import argparse
import sys
import json
import os
from collections import OrderedDict

def parse_value(value_str):
    if value_str.startswith('-') or value_str.replace('-', '', 1).isdigit():
        return int(value_str)
    return value_str

def add_records(data_file, records):
    with open(data_file, 'a') as f:
        for key, value in records.items():
            f.write(f"{key}={value}\n")
    return data_file

def read_records(data_file):
    records = OrderedDict()
    if os.path.exists(data_file):
        with open(data_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line:
                    key, value = line.split('=', 1)
                    if key not in records:
                        records[key] = value
                    else:
                        records[key] = value
    return records

def get_all_columns(records):
    columns = set()
    for record in records:
        columns.update(record.keys())
    return sorted(columns, key=lambda x: records[list(records.keys())[0]].keys().index(x) if x in records[list(records.keys())[0]] else len(records[list(records.keys())[0]].keys()))
    # Correctly order by first occurrence
    first_occurrence = {}
    for record in records:
        for key in record:
            if key not in first_occurrence:
                first_occurrence[key] = len(first_occurrence)
    return sorted(first_occurrence.keys(), key=lambda k: first_occurrence[k])

def render_report(data_file, output_html):
    records = read_records(data_file)
    columns = get_all_columns(records)

    html = """<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Report</title>
</head>
<body>
    <table>
        <thead>
            <tr>
"""

    for col in columns:
        html += f"                <th>{col}</th>\n"

    html += """
            </tr>
        </thead>
        <tbody>
"""

    for record in records:
        row = []
        for col in columns:
            if col in record:
                row.append(record[col])
            else:
                row.append('')

        html += "<tr>\n"
        for val in row:
            html += f"                <td>{val}</td>\n"
        html += "            </tr>\n"

    html += """
        </tbody>
    </table>
</body>
</html>
"""

    with open(output_html, 'w') as f:
        f.write(html)

    print(len(records))

def main():
    parser = argparse.ArgumentParser(description='Generate and render report data.')
    subparsers = parser.add_subparsers(dest='command', required=True)

    add_parser = subparsers.add_parser('add', help='Add records to DATA_FILE')
    add_parser.add_argument('data_file', type=str, help='File to store records')
    add_parser.add_argument('key_value_pairs', nargs='+', help='Key=Value pairs')

    render_parser = subparsers.add_parser('render', help='Render report from DATA_FILE to OUTPUT_HTML')
    render_parser.add_argument('data_file', type=str, help='File containing records')
    render_parser.add_argument('output_html', type=str, help='Output HTML file')

    args = parser.parse_args()

    if args.command == 'add':
        records = OrderedDict()
        for pair in args.key_value_pairs:
            if '=' in pair:
                key, value = pair.split('=', 1)
                records[key] = parse_value(value)
        add_records(args.data_file, records)
    elif args.command == 'render':
        render_report(args.data_file, args.output_html)

if __name__ == '__main__':
    main()
